module Prob_8_8 (output done, input [15: 0] data_AR, data_BR, input  start, clock, reset_b);   Controller_P8_8 M0 (    Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, done,     start, AR_lt_0, AR_gt_0, AR_eq_0, clock, reset_b  );  Datapath_P8_8 M1 (    Overflow, AR_lt_0, AR_gt_0, AR_eq_0, data_AR, data_BR,     Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, clock, reset_b  );endmodulemodule Controller_P8_8 (  output reg Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR,   output done, input start, AR_lt_0, AR_gt_0, AR_eq_0, clock, reset_b);  parameter  S0 = 1'b0, S1 = 1'b1;  reg state, next_state;  assign done = (state == S0);  always @ (posedge clock, negedge reset_b)     if (!reset_b) state <= S0; else state <= next_state;  always @ (state, start, AR_lt_0, AR_gt_0, AR_eq_0) begin    Ld_AR_BR = 0;    Div_AR_x2_CR = 0;    Mul_BR_x2_CR = 0;    Clr_CR = 0;        case (state)      S0:		if (start) begin Ld_AR_BR = 1; next_state = S1; end      S1:		begin          		  next_state = S0;			 		   if (AR_lt_0) Div_AR_x2_CR = 1;		  		  else if (AR_gt_0) Mul_BR_x2_CR = 1;		  		  else if (AR_eq_0) Clr_CR = 1;				end      default:	next_state = S0;    endcase  endendmodulemodule Datapath_P8_8 (  output reg Overflow, output AR_lt_0, AR_gt_0, AR_eq_0, input [15: 0] data_AR, data_BR,   input Ld_AR_BR, Div_AR_x2_CR, Mul_BR_x2_CR, Clr_CR, clock, reset_b);  reg [15: 0]	AR, BR, CR;  assign 	AR_lt_0 = AR[15];  assign 	AR_gt_0 = (!AR[15]) && (| AR[14:0]);		// Reduction-OR  assign 	AR_eq_0 = (AR == 16'b0);  always @ (posedge clock, negedge reset_b)    if (!reset_b) begin AR <= 8'b0; BR <= 8'b0; CR <= 16'b0; end    else begin      if (Ld_AR_BR) begin AR <= data_AR; BR <= data_BR; end      else if (Div_AR_x2_CR) CR <= {AR[15], AR[15:1]};   // For compiler without arithmetic right shift      else if (Mul_BR_x2_CR) {Overflow, CR} <= (BR << 1);      else if (Clr_CR) CR <= 16'b0;    end  endmodule // Test plan Ð Verify;// Power-up reset// If AR < 0 divide AR by 2 and transfer to CR // If AR > 0 multiply AR by 2 and transfer to CR// If AR = 0 clear CR// Reset on-the-fly
module t_Prob_P8_8;  wire 		done;  reg [15: 0] 	data_AR, data_BR;  reg  		start, clock, reset_b;  reg [15: 0]	AR_mag, BR_mag, CR_mag;	// To illustrate 2s complement math  // Probes for displaying magnitude of numbers  always @ (M0.M1.AR)  			// Hierarchical dereferencing    if (M0.M1.AR[15]) AR_mag = ~M0.M1.AR+ 16'd1; else AR_mag = M0.M1.AR;  always @ (M0.M1.BR ) 			     if (M0.M1.BR[15]) BR_mag = ~M0.M1.BR+ 16'd1; else BR_mag = M0.M1.BR;  always @ (M0.M1.CR)  			     if (M0.M1.CR[15]) CR_mag = ~M0.M1.CR + 16'd1; else CR_mag = M0.M1.CR;  Prob_8_8 M0 (done, data_AR, data_BR, start, clock, reset_b);  initial #250 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork           reset_b = 0; 		// Power-up reset      #2 reset_b = 1;     #50 reset_b = 0;	// Reset on-the-fly    #52 reset_b = 1;    #90 reset_b = 1;    #92 reset_b = 1;  join  initial fork    #20 start = 1;    #30 start = 0;    #70 start = 1;    #110 start = 1;  join  initial fork    data_AR = 16'd50;		// AR > 0    data_BR = 16'd20;		// Result should be 40    #50 data_AR = 16'd20;    #50 data_BR = 16'd50;	// Result should be 100    #100 data_AR = 16'd50;    #100 data_BR = 16'd50;    #130 data_AR = 16'd0;	// AR = 0, result should clear CR    #160 data_AR = -16'd20;	// AR < 0, Verilog stores 16-bit 2s complement    #160 data_BR = 16'd50;	// Result should have magnitude10    #190 data_AR = 16'd20;	// AR < 0, Verilog stores 16-bit 2s complement    #190 data_BR = 16'hffff;	// Result should have overflow  joinendmodule